import { randomBytes } from 'node:crypto'
import { readFile, writeFile } from 'node:fs/promises'
import { parseEnv } from 'node:util'

const path = new URL('../.env.local', import.meta.url)
let existing = ''
try {
  existing = await readFile(path, 'utf8')
} catch (error) {
  if (error.code !== 'ENOENT') throw error
}
const values = parseEnv(existing)
let updated = existing

// The guest password is chosen by the owner, never generated by this script.
if (!Object.hasOwn(values, 'GUEST_PASSWORD')) {
  updated += '\n# Dein festes Gästepasswort (12 bis 512 Zeichen):\nGUEST_PASSWORD=\n'
}

// Only the internal cookie-signing key is random. Preserve existing keys.
if (!values.GUEST_SESSION_SECRET) {
  const secret = randomBytes(48).toString('base64url')
  if (Object.hasOwn(values, 'GUEST_SESSION_SECRET')) {
    updated = updated.replace(
      /^\s*(?:export\s+)?GUEST_SESSION_SECRET\s*=[^\r\n]*/m,
      `GUEST_SESSION_SECRET=${secret}`,
    )
  } else {
    updated += `\nGUEST_SESSION_SECRET=${secret}\n`
  }
}

if (updated !== existing) await writeFile(path, updated, { mode: 0o600 })

console.log('Trage dein festes Passwort in .env.local bei GUEST_PASSWORD ein (12 bis 512 Zeichen).')
console.log('Ein vorhandenes Passwort und ein vorhandener Sitzungsschlüssel bleiben unverändert.')
console.log('Danach Vite neu starten. Auf Vercel GUEST_PASSWORD separat als Server-Variable setzen.')
